// ─── Build ping requests pour chaque provider ─────────────────
const PROVIDERS = [
  { id: 'claude',     name: 'Claude (Anthropic)',  envKey: 'CLAUDE_API_KEY',     format: 'anthropic', url: 'https://api.anthropic.com/v1/messages',                                                    model: 'claude-haiku-4-5-20251001' },
  { id: 'groq',       name: 'Groq',                envKey: 'GROQ_API_KEY',        format: 'openai',    url: 'https://api.groq.com/openai/v1/chat/completions',                                          model: 'llama-3.3-70b-versatile' },
  { id: 'openrouter', name: 'OpenRouter',          envKey: 'OPENROUTER_API_KEY',  format: 'openai',    url: 'https://openrouter.ai/api/v1/chat/completions',                                           model: 'anthropic/claude-3-haiku' },
  { id: 'gemini',     name: 'Gemini Flash 2',      envKey: 'GEMINI_API_KEY',      format: 'gemini',    url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent',  model: 'gemini-2.0-flash' },
  { id: 'glm',        name: 'GLM-4 (ZhipuAI)',     envKey: 'GLM_API_KEY',         format: 'openai',    url: 'https://open.bigmodel.cn/api/paas/v4/chat/completions',                                   model: 'glm-4-flash' }
];

// Filtrer les providers dont la clé est configurée
const active = PROVIDERS.filter(p => {
  const key = $env[p.envKey];
  return key && !key.includes('CHANGE_ME');
});

if (active.length === 0) {
  console.log('[WF11] Aucun provider configuré.');
  return [];
}

console.log(`[WF11] Ping de ${active.length} provider(s) : ${active.map(p => p.id).join(', ')}`);
return active.map(p => ({ json: p }));

// ─── Ping un provider et mesure la latence ────────────────────
const p = $input.item.json;
const apiKey = $env[p.envKey];
if (!apiKey || apiKey.includes('CHANGE_ME')) {
  return [{ json: { ...p, status: 'no_key', latency_ms: null, error: 'Clé API manquante' } }];
}

const t0 = Date.now();
let status = 'error';
let latency_ms = null;
let model_used = null;
let tokens_out = 0;
let errorMsg = null;

try {
  let url, headers, body;

  if (p.format === 'anthropic') {
    url = p.url;
    headers = { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' };
    body = { model: p.model, max_tokens: 5, system: 'Reply with one word only.', messages: [{ role: 'user', content: 'Ping' }] };
  } else if (p.format === 'openai') {
    url = p.url;
    headers = { 'Authorization': `Bearer ${apiKey}`, 'content-type': 'application/json' };
    if (p.id === 'openrouter') headers['HTTP-Referer'] = 'https://autoreach.local';
    body = { model: p.model, max_tokens: 5, messages: [{ role: 'user', content: 'Ping' }] };
  } else if (p.format === 'gemini') {
    url = `${p.url}?key=${apiKey}`;
    headers = { 'content-type': 'application/json' };
    body = { contents: [{ parts: [{ text: 'Reply with one word: Pong' }] }], generationConfig: { maxOutputTokens: 5 } };
  }

  const res = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body) });
  latency_ms = Date.now() - t0;

  if (!res.ok) {
    const errTxt = await res.text().catch(() => '');
    throw new Error(`HTTP ${res.status}: ${errTxt.substring(0, 200)}`);
  }

  const data = await res.json();

  if (p.format === 'anthropic') {
    model_used = data?.model;
    tokens_out = data?.usage?.output_tokens || 0;
  } else if (p.format === 'openai') {
    model_used = data?.model;
    tokens_out = data?.usage?.completion_tokens || 0;
  } else if (p.format === 'gemini') {
    model_used = p.model;
    tokens_out = data?.usageMetadata?.candidatesTokenCount || 0;
  }

  status = 'success';
  console.log(`[WF11] ✅ ${p.name} OK | ${latency_ms}ms`);
} catch(err) {
  latency_ms = Date.now() - t0;
  errorMsg = err.message.substring(0, 300);
  status = errorMsg.toLowerCase().includes('timeout') ? 'timeout' : 'error';
  console.error(`[WF11] ❌ ${p.name} FAILED: ${errorMsg}`);
}

return [{ json: {
  provider:      p.id,
  provider_name: p.name,
  status,
  model_used,
  latency_ms,
  tokens_output: tokens_out,
  error_message: errorMsg,
  was_failover:  false,
  recorded_at:   new Date().toISOString()
} }];

// ─── Agrège tous les résultats du batch ───────────────────────
const results = $input.all().map(i => i.json);

const healthy  = results.filter(r => r.status === 'success');
const failed   = results.filter(r => r.status !== 'success');
const allOk    = failed.length === 0;

// Ne générer une alerte Discord que si :
//   - au moins 1 provider est en erreur ET
//   - le provider principal (claude) est en erreur
const primaryFailed = results.find(r => r.provider === 'claude' && r.status !== 'success');

if (!primaryFailed && failed.length === 0) {
  console.log('[WF11] Tous les providers sont OK.');
  return [];
}

const statusEmoji = r => r.status === 'success' ? '✅' : r.status === 'timeout' ? '⏰' : '❌';
const latencyStr  = r => r.latency_ms ? `${r.latency_ms}ms` : 'N/A';

const lines = results.map(r =>
  `${statusEmoji(r)} **${r.provider_name}** — ${r.status} (${latencyStr(r)})${r.error_message ? ` — ${r.error_message.substring(0,80)}` : ''}`
).join('\n');

const color = primaryFailed ? 15158332 : 16753920; // rouge si claude down, orange sinon

return [{
  json: {
    embeds: [{
      title: primaryFailed
        ? '🚨 Provider AI principal hors ligne !'
        : `⚠️ ${failed.length} provider(s) AI en erreur`,
      description: `Bilan du health check — ${new Date().toLocaleTimeString('fr-FR')}`,
      color,
      fields: [
        { name: '📊 Résultats', value: lines, inline: false },
        { name: '✅ Opérationnels', value: `${healthy.length}/${results.length}`, inline: true },
        { name: '🔄 Failover actif', value: primaryFailed ? `→ ${healthy[0]?.provider_name || 'aucun'}` : 'Non nécessaire', inline: true }
      ],
      footer: { text: `WF11 Provider Monitor • v4` },
      timestamp: new Date().toISOString()
    }]
  }
}];
